/// <summary>
/// Bug 339828 - Request change on purchase order does not update auto submission field on METPurchTable
/// </summary>
[ExtensionOf(formControlStr(PurchTable, buttonRequestChange))]
final class METPurchTable_buttonRequestChange_Extension
{
}

Method.Source:
/// <summary>
/// Overrides click event of request change button on purchase order.
/// </summary>
/// <remarks>Update auto submission value based on request change.</remarks>
public void clicked()
{
    PurchTable purchtable = this.formRun().dataSource(formDataSourceStr(Purchtable,PurchTable)).cursor();
    METPurchTable metPurchTable = METPurchTable::find(purchtable.PurchId);
    if (metPurchTable)
    {
        ttsbegin;
            metPurchTable.selectForUpdate(true);
            metPurchTable.AutoSubmission = NoYes::No;
            metPurchTable.update(); 
        ttscommit;
    }
    next clicked();
}
